const plan=global.P2WoodPlan;if(!plan?.path?.length)throw Error('NO_PLAN');const v=a=>new Vec3(...a);const blockBudget=()=>bot.inventory.items().filter(i=>['sandstone','cobblestone','granite','andesite','diorite','dirt'].includes(i.name)).reduce((s,i)=>s+i.count,0);async function center(q){for(let j=0;j<20&&(Math.abs(bot.entity.position.x-q.x-.5)>.12||Math.abs(bot.entity.position.z-q.z-.5)>.12);j++){await bot.lookAt(q.offset(.5,1.4,.5),true);bot.setControlState('sneak',true);bot.setControlState('forward',true);await tick(1);bot.clearControlStates();await tick(2)}if(Math.abs(bot.entity.position.x-q.x-.5)>.18||Math.abs(bot.entity.position.z-q.z-.5)>.18)throw Error('CENTER')}
