async function center(x,z){for(const[axis,t]of[['x',x+.5],['z',z+.5]]){for(let k=0;k<35&&Math.abs(bot.entity.position[axis]-t)>.03;k++){life();await bot.lookAt(bot.entity.position.offset(axis==='x'?Math.sign(t-bot.entity.position.x)*3:0,0,axis==='z'?Math.sign(t-bot.entity.position.z)*3:0),true);bot.setControlState('sneak',true);bot.setControlState('forward',true);await ticks(1);bot.clearControlStates();await ticks(2);}if(Math.abs(bot.entity.position[axis]-t)>.08)throw Error('CENTER');}}
async function put(p){if(full(bot.blockAt(p)))return;const item=bot.inventory.items().find(i=>i.name==='dirt');if(!item)throw Error('DIRT_EMPTY');const ref=dirs.map(([x,z])=>p.offset(x,0,z)).find(q=>full(bot.blockAt(q)));if(!ref)throw Error('NO_SIDE_REF');await bot.equip(item,'hand');await bot._placeBlockWithOptions(bot.blockAt(ref),p.minus(ref),{forceLook:true,swingArm:'right'});await ticks(5);if(!full(bot.blockAt(p)))throw Error('PUT_REFUSED');}
async function reopen(){if(!hull(origin.cells||[origin.feet])||count()<2)throw Error('ORIGIN_OR_RESERVE');await center(origin.feet.x,origin.feet.z);if(!['dirt','grass_block'].includes(bot.blockAt(origin.cap).name))throw Error('OWN_CAP_KIND');await bot.unequip('hand');await bot.dig(bot.blockAt(origin.cap));opened=true;for(let k=0;k<20&&count()<3;k++)await ticks(1);if(count()<3)throw Error('CAP_RECEIPT');for(let j=0;j<3;j++){const y=origin.feet.y+j,p=new Vec3(origin.feet.x,y,origin.feet.z),base=p.offset(0,-1,0);if(!full(bot.blockAt(base)))throw Error('UP_BASE');await bot.equip(bot.inventory.items().find(i=>i.name==='dirt'),'hand');bot.setControlState('jump',true);try{for(let k=0;k<20&&bot.entity.position.y<y+1.16;k++)await ticks(1);if(bot.entity.position.y<y+1.15)throw Error('UP_HEIGHT');await bot._placeBlockWithOptions(bot.blockAt(base),new Vec3(0,1,0),{forceLook:true,swingArm:'right'});}finally{bot.setControlState('jump',false);}await settle(y+1);if(!full(bot.blockAt(p)))throw Error('UP_NO_ACK');}opened=false;console.log('UP3_ACTUAL',bot.entity.position.toString(),count());}
function suitable(x,top,z){const f=new Vec3(x,top-3,z);return[0,1,2].every(d=>['grass_block','dirt'].includes(bot.blockAt(new Vec3(x,top-1-d,z))?.name))&&full(bot.blockAt(f.offset(0,-1,0)))&&dirs.every(([dx,dz])=>[0,1,2].every(y=>full(bot.blockAt(f.offset(dx,y,dz)))))&&[0,1].every(y=>bot.blockAt(new Vec3(x,top+y,z))?.boundingBox==='empty');}
function sites(x,z,r=5){const found=[];for(let dx=-r;dx<=r;dx++)for(let dz=-r;dz<=r;dz++)for(let y=61;y<=74;y++)if(suitable(Math.floor(x)+dx,y,Math.floor(z)+dz))found.push(new Vec3(Math.floor(x)+dx,y,Math.floor(z)+dz));return found.sort((a,b)=>Math.hypot(a.x-x,a.z-z)-Math.hypot(b.x-x,b.z-z));}
function movement(){const m=new Movements(bot);m.canDig=false;m.canOpenDoors=false;m.allowSprinting=false;m.allowParkour=false;m.allow1by1towers=false;m.scafoldingBlocks=[];m.maxDropDown=2;for(const n of['water','lava','fire','magma_block','sweet_berry_bush','nether_portal','powder_snow'])if(bot.registry.blocksByName[n])m.blocksToAvoid.add(bot.registry.blocksByName[n].id);const prior=m.getNeighbors.bind(m);m.getNeighbors=n=>prior(n).filter(v=>Math.abs(v.y-n.y)<=1&&!Object.values(bot.entities).some(e=>['skeleton','stray','witch','creeper','zombie','zombie_villager','spider','drowned'].includes(e.name)&&e.position.distanceTo(new Vec3(v.x+.5,v.y,v.z+.5))<(['skeleton','stray','witch'].includes(e.name)?16:e.name==='creeper'?9:6)));bot.pathfinder.setMovements(m);bot.pathfinder.thinkTimeout=1500;}
async function go(p,ms){movement();let timer,damaged=false;const hurt=e=>{if(e===bot.entity){damaged=true;bot.pathfinder.setGoal(null);}};bot.on('entityHurt',hurt);try{await Promise.race([bot.pathfinder.goto(new goals.GoalBlock(p.x,p.y,p.z)),new Promise((_,r)=>timer=setTimeout(()=>{bot.pathfinder.setGoal(null);r(Error('NAV_BOUND'));},ms))]);}finally{clearTimeout(timer);bot.removeListener('entityHurt',hurt);bot.pathfinder.setGoal(null);bot.clearControlStates();}await ticks(4);if(damaged||!bot.entity.onGround||!bot.entity.position.floored().equals(p))throw Error('NAV_NOT_ACTUAL');}
async function bury(p){downSite=p;await center(p.x,p.z);if(!suitable(p.x,p.y,p.z))throw Error('SITE_CHANGED');for(let j=0;j<3;j++){await bot.unequip('hand');await bot.dig(bot.blockAt(p.offset(0,-1-j,0)));downSteps++;await settle(p.y-1-j);}await put(p.offset(0,-1,0));const f=p.offset(0,-3,0);sealed=hull([f])&&bot.entity.onGround&&bot.entity.position.floored().equals(f);if(!sealed)throw Error('NEW_HULL_FALSE');global.P3FoodStage={feet:f,cells:[f],cap:p.offset(0,-1,0),surface:p,at:Date.now()};}
async function rollback(){bot.pathfinder.setGoal(null);bot.clearControlStates();if(hull(origin.cells||[origin.feet])&&(origin.cells||[origin.feet]).some(p=>p.equals(bot.entity.position.floored()))&&bot.entity.onGround){sealed=true;return;}if(downSite&&downSteps){for(let j=downSteps;j<3;j++){await bot.unequip('hand');await bot.dig(bot.blockAt(downSite.offset(0,-1-j,0)));downSteps++;await settle(downSite.y-1-j);}await put(downSite.offset(0,-1,0));const f=downSite.offset(0,-3,0);sealed=hull([f]);if(sealed)global.P3FoodStage={feet:f,cells:[f],cap:downSite.offset(0,-1,0),surface:downSite,at:Date.now()};return;}
if(opened){for(let j=0;j<3&&bot.entity.position.y>origin.feet.y+.2;j++){await ticks(3);const y=Math.floor(bot.entity.position.y)-1,p=new Vec3(origin.feet.x,y,origin.feet.z);if(bot.blockAt(p).name!=='dirt')throw Error('ROLLBACK_KIND');await bot.unequip('hand');await bot.dig(bot.blockAt(p));await settle(y);}await put(origin.cap);sealed=hull(origin.cells||[origin.feet]);return;}
const here=bot.entity.position.floored();if(suitable(here.x,here.y,here.z)){await bury(here);return;}const options=sites(bot.entity.position.x,bot.entity.position.z,3);if(!options.length)throw Error('NO_LOCAL_FALLBACK');await go(options[0],5000);await bury(options[0]);}
try{life();if(bot.time.timeOfDay>11000)throw Error('NOT_DAY');const options=sites(...targetXZ);if(!options.length)throw Error('NO_TARGET_SITE');phase='PREFLIGHT';movement();const gen=bot.pathfinder.getPathFromTo(bot.pathfinder.movements,origin.surface.offset(.5,0,.5),new goals.GoalBlock(options[0].x,options[0].y,options[0].z),{timeout:1500,tickTimeout:100});let pr;for(let k=0;k<30;k++){const r=gen.next();if(r.value)pr=r.value.result;if(r.done||pr?.status!=='partial')break;}console.log('PREFLIGHT',pr?.status,pr?.path?.length,options[0].toString());if(pr?.status!=='success')throw Error('PRE_PATH_'+pr?.status);phase='UP';await reopen();phase='WALK';await go(options[0],25000);phase='DOWN';await bury(options[0]);phase='DONE';}catch(e){issue=e.message;console.log('STAGE_ISSUE',phase,issue);if(!lost){try{await rollback();}catch(e){console.log('ENDING_FAILED',e.message);}}}finally{bot.clearControlStates();bot.pathfinder.setGoal(null);bot.removeListener('death',dead);bot.removeListener('respawn',dead);}
return{phase,issue,sealed,lost,stage:global.P3FoodStage,p:bot.entity.position,hp:bot.health,food:bot.food,dirt:count(),time:bot.time.timeOfDay};
